namespace Gordic.Pok.WebClient {

    @Decorators.gcontent
    export class GPokHromadneUzavreniKnihTab extends GContentBase {

        private gridUzaverkaStep1: JQuery<HTMLElement>;
        private gridUzaverkaStep2: JQuery<HTMLElement>;
        private probihaUzaverka: boolean;
        

        onContentReady() {

            var that = this;

            this.title = "Hromadná uzávěrka pokladních knih";
            this.setBreadcrumbs([{ caption: this.title, defaultAction: true }]);

            var wizard = new Gordic.Wizard();

            wizard.create(
                { content: that }
                , {
                    title: "Hromadné uzavření knih",
                    steps: [
                        {
                            caption: "Výběr knih k uzavření",
                            create: function (cnt, contentDiv, change) {

                                var gf = new Gordic.Data.GridFormat();
                                gf.addTextColumn({
                                    name: "ixp_den",
                                    caption: "jres:31302005", //RC 31302005 : PID
                                    sortable: false
                                })
                                    .addTextColumn({
                                        name: "nazev",
                                        caption: "Název knihy",
                                        sortable: false,
                                        width: 300
                                    }),


                                    that.isl.PokKniha.list(rq => {
                                        return {
                                            filters: {
                                                ico: that.gpc.ico,
                                                rok: that.gpc.rok,
                                                faze: that.gpc.faze,
                                                aktivita: [100, 300]
                                            }
                                        }
                                    })
                                        .get()
                                        .done(function (data) {

                                            that.gridUzaverkaStep1 = $("<div>")
                                                .appendTo(contentDiv)
                                                .gautofit()
                                                .ggrid<Gordic.Hpl.Interface.GPokKnihaDto>({
                                                    columnMode: "fit",     // fit (defaultne by melo byt toto), full
                                                    columns: gf,
                                                    multi: true,
                                                    defaultAction: new GAction({     //obsluzna akce, ktera se spousti dbl clickem nad radkem
                                                        name: "gridRowSelectedActStep0",
                                                        run: function (ev, ctx) {
                                                            //_this.actions.actContinue.run();
                                                        }
                                                    }),
                                                    data: data.data
                                                });

                                        });
                            },
                            change: function (cnt, $element, ctx) { // event na změnu kroku
                                ctx.stepsEnable[1] = true;
                                cnt["dataUzaverkaStep1"] = that.gridUzaverkaStep1.ggrid("getSelection");
                            }

                        },
                        {
                            caption: "Výsledek uzávěrky",
                            create: function (cnt, contentDiv, change) {

                                var data = cnt["dataUzaverkaStep1"];

                                let kontroly: Gordic.Hpl.Interface.GPokKontrolyDto = {};

                                kontroly.Kontrola1 = true;
                                kontroly.Kontrola2 = true;

                                that.probihaUzaverka = true;

                                cnt.beginOperation("Probíhá hromadné uzavření knih");
                                let counter = 0;

                                data.forEach(function (row) {                                  
                                    that.hromadneUzavreniOne(row, true, kontroly).always(function () {
                                        counter = counter + 1;

                                        if (counter == data.length) {
                                            cnt.endOperation();
                                            that.probihaUzaverka = false;
                                        }

                                    })  
                                });

                                var gf = new Gordic.Data.GridFormat();
                                gf.addIconColumn({
                                    name: "stav",
                                    caption: "",
                                    width: 30,                                  
                                    //fixedwidth: true,
                                    sortable: true,
                                    description: "Stav",
                                    iconTemplate: function (metarow) {
                                        if (metarow.stav == 0)
                                            return { icon: "fa-check-circle", text:"OK", tooltip: "" };
                                        if (metarow.stav > 0)
                                            return { icon: "fa-question-circle", text :"?",tooltip: "" };
                                        if (metarow.stav < 0)
                                            return { icon: "fa-times-circle", text:"CHYBA",tooltip: "" };

                                    }
                                })
                                    .addTextColumn({
                                        name: "ixp_den",
                                        caption: "jres:31302005", //RC 31302005 : PID
                                        sortable: true
                                    })
                                    .addTextColumn({
                                        name: "nazev",
                                        caption: "Název knihy",
                                        sortable: true,
                                        width: 150
                                    })
                                    .addTextColumn({
                                        name: "vysledek",
                                        caption: "Výsledek",
                                        sortable: true,
                                        width: 300
                                    }),



                                    that.gridUzaverkaStep2 = $("<div>")
                                        .appendTo(contentDiv)
                                        .gautofit()
                                        .ggrid<Gordic.Hpl.Interface.GPokKnihaDto>({
                                            columnMode: "fit",     // fit (defaultne by melo byt toto), full
                                            columns: gf,                                          
                                            multi: true,
                                            defaultAction: new GAction({     //obsluzna akce, ktera se spousti dbl clickem nad radkem
                                                name: "gridRowSelectedActStep1",
                                                run: function (ev, ctx) {

                                                    var row = ctx.cellInfo.data;
                                                    if (row.stav < 0) {

                                                        that.dialogs.messageBox("Chyba", row.vysledek, [GDlg.mbbOk], GDlg.mbiError); //pouze oK a ne YES/NO
                                                    }
                                                    else if (row.stav == 0) {

                                                        //zobrazím okno že je vše ok

                                                        that.dialogs.messageBox("Oznámení", row.vysledek, [GDlg.mbbOk], GDlg.mbiSuccess); //pouze oK a ne YES/NO
                                                    }
                                                    else if (row.stav > 0) {

                                                        that.dialogs.messageBox("jres:31302192", row.vysledek, GDlg.mbbYesNo, GDlg.mbiQuestion) //RC 31302192 : Pokračovat
                                                            .on("close", function (ev, o, args) { // zeptám se a pokud ANO tak udělám akcu
                                                                if (o == "yes") {

                                                                    let kontroly: Gordic.Hpl.Interface.GPokKontrolyDto = { Kontrola1: true, Kontrola2: true };

                                                                    if (row.stav == 1)
                                                                        kontroly.Kontrola1 = false;

                                                                    //zatím zakomentováno, odstranění dokladů automaticky bez dotazu
                                                                    //if (row.stav == 2)
                                                                    //    kontroly.Kontrola2 = false;

                                                                    //if (row.stav == 2) {//&& that.HplRezSch) { // pokud mažu nějáké neuzavřené doklady tak se zeptám ješte na detail ohledně krytí rozpočtu
                                                                    //    that.dialogs.messageBox("Dotaz", "Vyřadit ze zpracování doklady, které neprojdou kontrolou rozpočtu?", GDlg.mbbYesNo, GDlg.mbiQuestion)
                                                                    //        .on("close", function (ev, o, args) { // zeptám se a pokud ANO tak udělám akcu
                                                                    //            if (o == "yes") {

                                                                    //                that.hromadneUzavreniOne( row, true, kontroly);

                                                                    //            }
                                                                    //            else if (o == "no") {
                                                                    //                that.hromadneUzavreniOne( row, false, kontroly);
                                                                    //            }; // end yes/no


                                                                    //        }); //end dialogs vyradit ze zpracovani ...
                                                                    //}
                                                                    //else {

                                                                        that.hromadneUzavreniOne( row, false, kontroly);

                                                                    //}//end if row.stav == 2 and param

                                                                } //end yes
                                                            });//end dialog message question
                                                    } //end if row.stav > 0

                                                }
                                            }),
                                            data: new Gordic.Data.View(cnt["dataUzaverkaStep1"], { key: "ixp_den" })
                                        });
                            },
                            change: function (cnt, $element, ctx) { // event na změnu kroku
                                // ctx.stepsEnable[2] = true;
                                //  cnt.step1Selection = cnt.$grid.ggrid("getSelection");
                            }

                        }
                    ],
                    complete: function (gcontent, contentDiv, change) {
                        gcontent.tryClose();
                    }
                });




        }

        closing() { //funkce pro zavření detailu
            var that = this;

            var def = $.Deferred();


            if (that.probihaUzaverka) {
                that.showFlash("Právě probíhá hromadná uzávěrka, okno nelze opustit!", "warning",)
                def.reject();
            }
            else {

                def.resolve();
            }


            return def.promise();


        }

        private hromadneUzavreniOne(row: any, kontrolaRozpocet: boolean, kontroly: Gordic.Hpl.Interface.GPokKontrolyDto): JQueryPromise<void> {

            var that = this;

            var def = $.Deferred();


            that.isl.PokKniha.uzaverkaRocni({ ixpDen: row.ixp_den, kontrolaRozpocet: kontrolaRozpocet, kontroly: kontroly })
                .get()
                .done(function (vysledek) {
                    row.stav = 0;
                    row.vysledek = vysledek;
                    that.gridUzaverkaStep2.ggrid("getView").updateData(row, "update");
                    that.gridUzaverkaStep2.ggrid("getView").getDataRows(true).forEach(function (meta) { if (meta.data.stav === 0) meta.checked = true; });
                    that.gridUzaverkaStep2.ggrid("refreshRows");
                    def.resolve();

                })
                .fail(function (xhr, typ, obj) {
                    if (typ === "exception") {
                        if (obj.baseType === "Gordic.General.GHplValidationException") {
                            obj.handled = true;
                            row.stav = -1;
                            row.vysledek = obj.baseMessage;
                            that.gridUzaverkaStep2.ggrid("getView").updateData(row, "update");
                            that.gridUzaverkaStep2.ggrid("getView").getDataRows(true).forEach(function (meta) { if (meta.data.stav === 0) meta.checked = true; });
                            that.gridUzaverkaStep2.ggrid("refreshRows");
                        }
                        else if (obj.data.member == "Kontrola1") {
                            obj.handled = true;
                            row.stav = 1;
                            row.vysledek = obj.baseMessage + "</ Pokračovat>";
                            that.gridUzaverkaStep2.ggrid("getView").updateData(row, "update");
                            that.gridUzaverkaStep2.ggrid("getView").getDataRows(true).forEach(function (meta) { if (meta.data.stav === 0) meta.checked = true; });
                            that.gridUzaverkaStep2.ggrid("refreshRows");
                        }
                        else if (obj.data.member == "Kontrola2") {
                            obj.handled = true;
                            row.stav = 2;
                            row.vysledek = obj.baseMessage + "</ Pokračovat>";
                            that.gridUzaverkaStep2.ggrid("getView").updateData(row, "update");
                            that.gridUzaverkaStep2.ggrid("getView").getDataRows(true).forEach(function (meta) { if (meta.data.stav === 0) meta.checked = true; });
                            that.gridUzaverkaStep2.ggrid("refreshRows");
                        }
                    }

                    def.reject();
                });

            return def.promise();


        }


    }


}


